import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    w = data[1:1 + n]
    m = int(data[1 + n])
    need = set(data[2 + n:2 + n + m])
    k = len(need)
    cnt = {}
    have = 0
    best = None
    l = 0
    for r in range(n):
        x = w[r]
        if x in need:
            cnt[x] = cnt.get(x, 0) + 1
            if cnt[x] == 1:
                have += 1
        while have == k:
            if best is None or r - l < best[1] - best[0]:
                best = (l, r)
            y = w[l]
            if y in need:
                cnt[y] -= 1
                if cnt[y] == 0:
                    have -= 1
            l += 1
    print(' '.join(w[best[0]:best[1] + 1]))

main()

